66	+/// # Turn checkpoint
67	+///
68	+/// This runtime cannot support a turn checkpoint yet. If the context that
69	+/// `build` returns carries one (set with `RunContext::with_turn_checkpoint`),
70	+/// the server clears it and logs a warning. The checkpoint never runs.
71	+///
72	 /// # `?Send` futures
73	 ///
74	 /// `actix_web::HttpRequest` wraps an `Rc` internally and is therefore `!Sync`
75	 /// (so `&HttpRequest` is `!Send`). Any implementation that actually reads from
76	 /// `req` — the common case, e.g. parsing a JWT from the headers — captures a
77	 /// `!Send` reference in its future, so this trait is declared
78	 /// `#[async_trait(?Send)]`: the returned future is not required to be `Send`.
79	 /// The server awaits `build` on the worker thread that received the request
80	 /// (before it hands the resulting `RunContext`, which *is* `Send`, to the run's
81	 /// writer task), matching actix-web's request-bound execution model. The trait
82	@@ -145,20 +151,39 @@ where
83	         _req: &HttpRequest,
84	         session: Arc<dyn Session>,
85	         cancel: CancellationToken,
86	     ) -> Result<RunContext<Ctx>, ServerError> {
87	         Ok(RunContext::ephemeral(Ctx::default())
88	             .with_session(session)
89	             .with_cancel(cancel))
