93	+/// Strip the run features that this runtime cannot support yet.
94	+///
95	+/// The turn checkpoint needs a host that can stay with the run between turns.
96	+/// This runtime cannot do that, so the helper clears a checkpoint that the
97	+/// context provider set, and logs a warning. It logs only when a checkpoint
98	+/// was set.
99	+pub(crate) fn restrict_unsupported_run_features<Ctx>(ctx: RunContext<Ctx>) -> RunContext<Ctx>
100	+where
101	+    Ctx: Send + Sync + 'static,
102	+{
103	+    if ctx.turn_checkpoint().is_some() {
104	+        tracing::warn!(
105	+            target: "paigasus::runtime_actix::context",
106	+            "turn checkpoint is not supported by this runtime; ignored"
107	+        );
108	+    }
109	+    ctx.without_turn_checkpoint()
110	+}
