253	+/// A checkpoint that counts its calls.
254	+struct CountingCheckpoint(Arc<std::sync::atomic::AtomicUsize>);
255	+
256	+#[async_trait::async_trait]
257	+impl paigasus_helikon_core::TurnCheckpoint<()> for CountingCheckpoint {
258	+    async fn at_boundary(
259	+        &self,
260	+        _ctx: &paigasus_helikon_core::RunContext<()>,
261	+        _boundary: &paigasus_helikon_core::TurnBoundary,
262	+    ) -> paigasus_helikon_core::CheckpointDecision {
263	+        self.0.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
264	+        paigasus_helikon_core::CheckpointDecision::Continue
265	+    }
266	+}
267	+
268	+/// A provider that sets a counting checkpoint on every context.
269	+struct CheckpointProvider(Arc<std::sync::atomic::AtomicUsize>);
270	+
271	+#[async_trait::async_trait(?Send)]
272	+impl paigasus_helikon_runtime_actix::ContextProvider<()> for CheckpointProvider {
273	+    async fn build(
274	+        &self,
275	+        _req: &actix_web::HttpRequest,
276	+        session: Arc<dyn paigasus_helikon_core::Session>,
277	+        cancel: tokio_util::sync::CancellationToken,
278	+    ) -> Result<paigasus_helikon_core::RunContext<()>, paigasus_helikon_runtime_actix::ServerError>
279	+    {
280	+        Ok(paigasus_helikon_core::RunContext::ephemeral(())
281	+            .with_session(session)
282	+            .with_cancel(cancel)
283	+            .with_turn_checkpoint(Arc::new(CountingCheckpoint(Arc::clone(&self.0)))))
284	+    }
285	+}
