287	+/// An agent that makes one tool turn: it calls the turn checkpoint at the
288	+/// boundary, as the agent loop does, when the context carries one.
289	+struct OneTurnAgent;
290	+
291	+#[async_trait::async_trait]
292	+impl paigasus_helikon_core::Agent<()> for OneTurnAgent {
293	+    fn name(&self) -> &str {
294	+        "probe"
295	+    }
296	+
297	+    fn description(&self) -> &str {
298	+        "calls the turn checkpoint once"
299	+    }
300	+
301	+    async fn run(
302	+        &self,
303	+        ctx: paigasus_helikon_core::RunContext<()>,
304	+        _input: paigasus_helikon_core::AgentInput,
305	+    ) -> Result<
306	+        futures_util::stream::BoxStream<'static, AgentEvent>,
307	+        paigasus_helikon_core::AgentError,
308	+    > {
309	+        use futures_util::StreamExt as _;
310	+        if let Some(cp) = ctx.turn_checkpoint() {
311	+            let boundary = paigasus_helikon_core::TurnBoundary::new(0, 1, "probe", 0);
312	+            cp.at_boundary(&ctx, &boundary).await;
313	+        }
314	+        let events = vec![AgentEvent::RunCompleted {
315	+            usage: paigasus_helikon_core::TokenUsage::default(),
316	+        }];
317	+        Ok(futures_util::stream::iter(events).boxed())
318	+    }
319	+}
